(12,13,655,'hamedmohammadithabet','حامد محمدی ثابت','روانشناس بالینی،درمانگر CBT، طرحواره درمانگر، هیپنوتراپیست، مشاوره فردی، روانسنج تست های روانشناختی',1,1,1,'{\"articles\":\"12\",\"services\":{\"1\":{\"title\":\"\\u0627\\u06a9\\u0648 \\u0648 \\u0646\\u0648\\u0627\\u0631 \\u0642\\u0644\\u0628 \\u06a9\\u0627\\u0645\\u0644\",\"desc\":\"\\u0628\\u0631\\u0631\\u0633\\u06cc \\u0639\\u0645\\u0644\\u06a9\\u0631\\u062f \\u0642\\u0644\\u0628 \\u0628\\u0627 \\u062a\\u0635\\u0648\\u06cc\\u0631\\u0628\\u0631\\u062f\\u0627\\u0631\\u06cc \\u062f\\u0642\\u06cc\\u0642 \\u0648 \\u0622\\u0646\\u0627\\u0644\\u06cc\\u0632 \\u0633\\u06cc\\u06af\\u0646\\u0627\\u0644\\u200c\\u0647\\u0627.\"},\"2\":{\"title\":\"\\u0645\\u0627\\u0646\\u06cc\\u062a\\u0648\\u0631\\u06cc\\u0646\\u06af \\u06f2\\u06f4 \\u0633\\u0627\\u0639\\u062a\\u0647 \\u0628\\u0627 \\u0647\\u0648\\u0644\\u062a\\u0631 \\u0642\\u0644\\u0628\\u06cc\",\"desc\":\"\\u0628\\u0631\\u0627\\u06cc \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0646\\u0627\\u0645\\u0646\\u0638\\u0645\\u06cc \\u0636\\u0631\\u0628\\u0627\\u0646 \\u062f\\u0631 \\u0634\\u0631\\u0627\\u06cc\\u0637 \\u0631\\u0648\\u0632\\u0645\\u0631\\u0647.\"},\"3\":{\"title\":\"\\u062a\\u0633\\u062a \\u0648\\u0631\\u0632\\u0634 \\u0648 \\u0627\\u0631\\u0632\\u06cc\\u0627\\u0628\\u06cc \\u0639\\u0645\\u0644\\u06a9\\u0631\\u062f \\u0642\\u0644\\u0628 \\u062a\\u062d\\u062a \\u0627\\u0633\\u062a\\u0631\\u0633\",\"desc\":\"\\u0628\\u0631\\u0631\\u0633\\u06cc \\u067e\\u0627\\u0633\\u062e \\u0642\\u0644\\u0628 \\u0628\\u0647 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0641\\u06cc\\u0632\\u06cc\\u06a9\\u06cc \\u06a9\\u0646\\u062a\\u0631\\u0644\\u200c\\u0634\\u062f\\u0647.\"},\"4\":{\"title\":\"\\u062f\\u0631\\u0645\\u0627\\u0646 \\u0627\\u062e\\u062a\\u0644\\u0627\\u0644\\u0627\\u062a \\u0631\\u06cc\\u062a\\u0645 \\u0642\\u0644\\u0628 (\\u0622\\u0631\\u06cc\\u062a\\u0645\\u06cc)\",\"desc\":\"\\u0628\\u0627 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u0627\\u0632 \\u062f\\u0627\\u0631\\u0648 \\u0648 \\u062a\\u0646\\u0638\\u06cc\\u0645 \\u0633\\u0628\\u06a9 \\u0632\\u0646\\u062f\\u06af\\u06cc.\"},\"5\":{\"title\":\"\\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0628\\u0627\\u0644\\u0627 \\u0648 \\u067e\\u0627\\u06cc\\u06cc\\u0646\",\"desc\":\"\\u067e\\u0627\\u06cc\\u0634 \\u0631\\u0648\\u0632\\u0627\\u0646\\u0647\\u060c \\u0645\\u0634\\u0627\\u0648\\u0631\\u0647 \\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0648 \\u062f\\u0627\\u0631\\u0648\\u0647\\u0627\\u06cc \\u062c\\u062f\\u06cc\\u062f.\"},\"6\":{\"title\":\"\\u0645\\u0634\\u0627\\u0648\\u0631\\u0647 \\u0648 \\u0686\\u06a9\\u0627\\u067e \\u067e\\u06cc\\u0634\\u06af\\u06cc\\u0631\\u0627\\u0646\\u0647 \\u0642\\u0644\\u0628\",\"desc\":\"\\u0645\\u0646\\u0627\\u0633\\u0628 \\u0627\\u0641\\u0631\\u0627\\u062f \\u0628\\u0627\\u0644\\u0627\\u06cc \\u06f3\\u06f5 \\u0633\\u0627\\u0644 \\u06cc\\u0627 \\u062f\\u0627\\u0631\\u0627\\u06cc \\u0633\\u0627\\u0628\\u0642\\u0647 \\u062e\\u0627\\u0646\\u0648\\u0627\\u062f\\u06af\\u06cc \\u0628\\u06cc\\u0645\\u0627\\u0631\\u06cc \\u0642\\u0644\\u0628\\u06cc.\"}},\"faqs\":{\"1\":{\"question\":\"\\u06f1. \\u0622\\u06cc\\u0627 \\u0646\\u0648\\u0627\\u0631 \\u0642\\u0644\\u0628 \\u062f\\u0631 \\u0645\\u0637\\u0628 \\u06af\\u0631\\u0641\\u062a\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u061f\",\"answer\":\"\\u0628\\u0644\\u0647\\u060c \\u0646\\u0648\\u0627\\u0631 \\u0642\\u0644\\u0628 \\u0648 \\u062a\\u0633\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0627\\u0648\\u0644\\u06cc\\u0647 \\u0628\\u0647\\u200c\\u0635\\u0648\\u0631\\u062a \\u06a9\\u0627\\u0645\\u0644 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u0646\\u062f.\"},\"2\":{\"question\":\"\\u06f2. \\u0686\\u0647 \\u0632\\u0645\\u0627\\u0646\\u06cc \\u0628\\u0627\\u06cc\\u062f \\u0628\\u0647 \\u0645\\u062a\\u062e\\u0635\\u0635 \\u0642\\u0644\\u0628 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0647 \\u06a9\\u0631\\u062f\\u061f\",\"answer\":\"\\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u062f\\u0631\\u062f \\u0633\\u06cc\\u0646\\u0647\\u060c \\u062a\\u067e\\u0634 \\u0642\\u0644\\u0628\\u060c \\u0646\\u0641\\u0633\\u200c\\u062a\\u0646\\u06af\\u06cc \\u06cc\\u0627 \\u0633\\u0627\\u0628\\u0642\\u0647 \\u062e\\u0627\\u0646\\u0648\\u0627\\u062f\\u06af\\u06cc \\u0628\\u06cc\\u0645\\u0627\\u0631\\u06cc \\u0642\\u0644\\u0628\\u06cc.\"},\"3\":{\"question\":\"\\u06f3. \\u0622\\u06cc\\u0627 \\u0627\\u0645\\u06a9\\u0627\\u0646 \\u062a\\u0633\\u062a \\u0648\\u0631\\u0632\\u0634 \\u062f\\u0631 \\u0645\\u0637\\u0628 \\u0648\\u062c\\u0648\\u062f \\u062f\\u0627\\u0631\\u062f\\u061f\",\"answer\":\"\\u0628\\u0644\\u0647\\u060c \\u062a\\u0633\\u062a \\u0648\\u0631\\u0632\\u0634 \\u0648 \\u0627\\u06a9\\u0648\\u06cc \\u0642\\u0644\\u0628 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\"},\"4\":{\"question\":\"\\u06f4. \\u0622\\u06cc\\u0627 \\u062f\\u06a9\\u062a\\u0631 \\u0627\\u0645\\u06cc\\u0646\\u06cc \\u0632\\u0627\\u062f\\u0647 \\u062c\\u0631\\u0627\\u062d\\u06cc \\u0647\\u0645 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u0646\\u062f\\u061f\",\"answer\":\"\\u062e\\u06cc\\u0631\\u060c \\u062c\\u0631\\u0627\\u062d\\u06cc \\u062a\\u0648\\u0633\\u0637 \\u062c\\u0631\\u0627\\u062d \\u0642\\u0644\\u0628 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0627\\u0645\\u0627 \\u0627\\u06cc\\u0634\\u0627\\u0646 \\u062a\\u0634\\u062e\\u06cc\\u0635 \\u0648 \\u0627\\u0631\\u062c\\u0627\\u0639 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u0646\\u062f.\"},\"5\":{\"question\":\"\\u06f5. \\u0622\\u06cc\\u0627 \\u0645\\u0634\\u06a9\\u0644\\u0627\\u062a \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0647\\u0645 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u061f\",\"answer\":\"\\u0628\\u0644\\u0647\\u060c \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u06cc\\u06a9\\u06cc \\u0627\\u0632 \\u0645\\u0648\\u0627\\u0631\\u062f