(461,'_elementor_notifications_data','a:2:{s:7:\"timeout\";i:1790288934;s:5:\"value\";s:4983:\"[{\"id\":\"4.3-elementor-mcp\",\"featured\":true,\"title\":\"Connect any AI tool to build and manage your site with the Elementor MCP\",\"description\":\"Claude, Codex, Cursor, and other compatible AI tools can now connect to your site and generate atomic pages, refine complex layouts, and control your design system from natural language prompts.\",\"topic\":\"Elementor MCP\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/4.3-mcp.png\",\"chipTags\":[\"Atomic Editor\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-4.3-mcp-page\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"4.3-atomic-loop\",\"title\":\"Atomic Loop\",\"description\":\"Build dynamic, repeatable content layouts directly within the Atomic Editor. Display multiple posts, products, or custom content items using a single, customizable design template\",\"topic\":\"Atomic Editor\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/4.3-loop.png\",\"chipTags\":[\"Atomic Editor\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-4.3-atomic-loop-article\\/\",\"readMoreText\":\"Learn More\",\"cta\":\"Upgrade\",\"ctaLink\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-4.3-loop\\/\",\"conditions\":[[{\"type\":\"plugin\",\"operator\":\"!=\",\"plugin\":\"elementor-pro\\/elementor-pro.php\"}]]},{\"id\":\"4.3-accordion-bg-video\",\"title\":\"New Atomic Loop, Accordion, and Background video\",\"description\":\"Build dynamic, repeatable content layouts, expandable content blocks, and engaging video backgrounds, with full atomic control over every part of each element.\",\"topic\":\"Atomic Editor\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/4.3-accordion.png\",\"chipTags\":[\"Atomic Editor\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-4.3-features\\/\",\"readMoreText\":\"Learn More\",\"conditions\":[[{\"type\":\"plugin\",\"plugin\":\"elementor-pro\\/elementor-pro.php\"}]]},{\"id\":\"4.3-accordion-bg-video\",\"title\":\"Atomic Accordion and Background video\",\"description\":\"Create expandable content blocks and engaging video backgrounds, with full atomic control over every part of each element\",\"topic\":\"Atomic Editor\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/4.3-accordion.png\",\"chipTags\":[\"Atomic Editor\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-4.3-features\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"angie-build-full-page\",\"title\":\"Generate full Elementor pages\",\"description\":\"Describe the layout you need and get a complete page, or generate individual sections like hero areas, feature blocks, and pricing tables one at a time. Every result can be matched to your site\'s existing styles or follow any new design instructions you give.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-build-full-page.png\",\"chipTags\":[\"Angie\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-build-with-prompts\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"4.3-angie-build-design-system\",\"title\":\"AI-Powered page & design system generation from within the Editor\",\"description\":\"Describe the layout you need and get a complete page, or generate individual sections like hero areas, feature blocks, and pricing tables one at a time. You can create a brand new design system, or use your site\\u2019s existing styles.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-build-design-system.png\",\"chipTags\":[\"Angie\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-build-with-prompts\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"4.3-angie-super-community\",\"title\":\"Discover and share in the Angie Community Library\",\"description\":\"Access a curated catalog of verified snippets and custom widgets created by fellow builders. Import them without consuming any credits, remix them to fit your vision, or showcase your own creations to the world.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-community.png\",\"chipTags\":[\"Angie\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-community\\/\",\"readMoreText\":\"Browse library\"},{\"id\":\"4.3-angie-super-admin\",\"title\":\"Super Admin Mode\",\"description\":\"Revolutionize your WordPress workflow with Super Admin Mode. Perform root-level WordPress operations through natural language - bulk post and product updates, PHP error diagnosis, and more.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-super-admin.png\",\"chipTags\":[\"Angie\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-super-admin\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"4.3-one-launch\",\"title\":\"Elementor One\",\"description\":\"The complete website building experience. All the tools to create, optimize, and manage websites, unified under one roof.\",\"topic\":\"Elementor One\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/one-launch.png\",\"chipTags\":[\"Elementor One\"],\"cta\":\"Explore Elementor One\",\"ctaLink\":\"https:\\/\\/go.elementor.com\\/launch-whats-new\"}]\";}','off'),
