INSERT INTO `Dj3i_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES (5,7,'_form','<label> نام شما\n    [text* your-name autocomplete:name] </label>\n\n<label> ایمیل شما\n    [email* your-email autocomplete:email] </label>\n\n<label> موضوع\n    [text* your-subject] </label>\n\n<label> پیغام شما (اختیاری)\n    [textarea your-message] </label>\n\n[submit \"ارسال\"]'),
(6,7,'_mail','a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:38:\"[_site_title] <drplus@amin-noorani.ir>\";s:9:\"recipient\";s:19:\"[_site_admin_email]\";s:4:\"body\";s:239:\"از : [your-name] [your-email]\nموضوع: [your-subject]\n\nمحتوای پیام :\n[your-message]\n\n-- \nاین یک اعلان است که یک فرم تماس در وب سایت شما ارسال شده است ([_site_title] [_site_url]).\";s:18:\"additional_headers\";s:22:\"Reply-To: [your-email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
(7,7,'_mail_2','a:9:{s:6:\"active\";b:0;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:38:\"[_site_title] <drplus@amin-noorani.ir>\";s:9:\"recipient\";s:12:\"[your-email]\";s:4:\"body\";s:342:\"محتوای پیام :\n[your-message]\n\n-- \nاین ایمیل یک رسید برای ارسال فرم تماس شما در وب سایت ما است ([_site_title] [_site_url]) که در آن از آدرس ایمیل شما استفاده شده است. اگر شما نبودید، لطفاً این پیام را نادیده بگیرید.\";s:18:\"additional_headers\";s:29:\"Reply-To: [_site_admin_email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
(8,7,'_messages','a:22:{s:12:\"mail_sent_ok\";s:88:\"از پیام شما متشکریم، پیام شما با موفقیت ارسال شد.\";s:12:\"mail_sent_ng\";s:112:\"مشکلی در ارسال پیام شما بوجود آمده است، لطفا دوباره تلاش کنید.\";s:16:\"validation_error\";s:137:\"یک یا چند تا از مقادیر وارد شده مشکل دارد، لطفا پس از بررسی دوباره تلاش کنید.\";s:4:\"spam\";s:112:\"مشکلی در ارسال پیام شما بوجود آمده است، لطفا دوباره تلاش کنید.\";s:12:\"accept_terms\";s:120:\"شما باید با شرایط و قوانین موافقت کنید تا قادر به ارسال پیام باشید.\";s:16:\"invalid_required\";s:50:\"لطفا این قسمت را تکمیل کنید.\";s:16:\"invalid_too_long\";s:60:\"این زمینه ورودی خیلی طولانی دارد.\";s:17:\"invalid_too_short\";s:60:\"این زمینه ورودی خیلی کوتاهی دارد.\";s:13:\"upload_failed\";s:64:\"مشکلی در آپلود فایل شما رخ داده است.\";s:24:\"upload_file_type_invalid\";s:79:\"شما اجازه ندارید از این نوع فایل آپلود کنید.\";s:21:\"upload_file_too_large\";s:62:\"پرونده بارگذاری شده خیلی بزرگ است.\";s:23:\"upload_failed_php_error\";s:64:\"مشکلی در آپلود فایل شما رخ داده است.\";s:12:\"invalid_date\";s:91:\"لطفا تاریخ را با فرمت YYYY-MM-DD (روز-ماه-سال) وارد کنید.\";s:14:\"date_too_early\";s:56:\"این زمینه تاریخ خیلی زودی دارد.\";s:13:\"date_too_late\";s:56:\"این زمینه تاریخ خیلی دیری دارد.\";s:14:\"invalid_number\";s:43:\"لطفا یک شماره وارد کنید.\";s:16:\"number_too_small\";s:62:\"این زمینه شماره بسیار کوتاهی دارد.\";s:16:\"number_too_large\";s:62:\"این زمینه شماره بسیار طولانی دارد.\";s:23:\"quiz_answer_not_correct\";s:52:\"جواب شما به آزمون اشتباه است.\";s:13:\"invalid_email\";s:52:\"لطفا یک آدرس ایمیل وارد کنید.\";s:11:\"invalid_url\";s:48:\"لطفا یک نشانی وب وارد کنید.\";s:11:\"invalid_tel\";s:52:\"لطفا یک شماره تلفن وارد کنید.\";}'),
