INSERT INTO `Dj3i_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1,30,'2025-01-06 10:46:36','2025-01-06 10:46:36','<h1>مشاوره تحصیلی و شغلی</h1>		<p>یکی از مسائل و دغدغه های جوانان امروزی، انتخاب شغل است که غالبا بدون توجه به زمینه های استعداد، علاقه، رغبت و هدف مشخص در زندگی تحصیلی و دوره مهارت آموزی انتخاب می‌گردد.</p><p>با توجه به اهمیت بسیشار زیاد انتخاب رشته ی صحیح و سپس انتخاب شغل مناسب در جامعه امروزی، روان‌درمان در این مقاله قصد دارد به معرفی تخصص مشاوره تحصیلی و شغلی پرداخته، ویژگی های یک مشاور تحصیلی و شغلی خوب را عنوان کرده و بهترین متخصصان کشور در این زمینه را معرفی نماید.</p><figure><img src=\"https://aghazgarclinic.ir/wp-content/uploads/2024/09/download-1-682x1024.jpeg\" alt=\"\" /></figure><h1><strong>مشاوره تحصیلی و شغلی چیست؟</strong></h1><p>در عصر جدید مشاغل دیگر ارثی نیستند بلکه پیشرفت سریع دانش و تکنولوژی موجب کثرت مشاغل، تقسیم کار فراوان و جلب استعدادهای مختلف شده است.</p><p>امروزه برای انجام اکثر کارها، نیاز به تحصیل دانش و کسب مهارت می‌باشد. از این رو توجه به رابطه تحصیل و شغل اهمیت دارد.</p><p>از آنجا که تحصیلات دبیرستانی و بالاتر زیرساز اشتغال آتی دانش آموزان و دانشجویان هم خواهند بود، لذا باید برمبنای گزینش های شغلی آینده برنامه ریزی و انتخاب شوند. برای انتخاب راه درست ابتدا باید در مورد آمادگی هایی که ممکن است از نظر فردی و حرفه ای ارزشمند باشند اندیشید و سپس برنامه ریزی و تصمیم گیری کرد.</p><h2>مشاوره تحصیلی مشاوره مدرسه</h2><p><strong>تعریف مشاوره تحصیلی</strong><br />مشاوره تحصیلی جریان یاری دهنده و منظمی است که به دانش آموز در انتخاب مناسب دروس، رشته و مهارت های تحصیلی کمک می‌کند تا سازگاری مطلوب را کسب کند.</p><p><strong>تعریف مشاوره شغلی</strong><br />مشاوره شغلی نوعی دیگر از مشاوره است، که بدان وسیله به فرد کمک می‌شود تا بر اساس شناخت استعدادها، محدودیت ها و نیز امکانات شغلی جامعه بتواند شغل مناسبی را پیدا کند.</p><h2>مشاوره شغلی خوب</h2><p><strong>رابطه مشاوره شغلی با مشاوره تحصیلی</strong><br />هر گونه راهنمایی شغلی باید بر مبنای وضع تحصیلی فرد انجام گیرد تا بهترین نتایج حاصل شود. مشاوره تحصیلی پایه و اساس محکمی برای مشاوره شغلی محسوب می‌شود.</p><p><strong>تاريخچه راهنمایی و مشاوره شغلی و حرفه ای</strong><br />راهنمایی شغلی به طور عام، با نظام استاد-شاگردی آغاز گردیده است و والدین در ابتدا، فرزندان خود را برای برعهده گرفتن شغل خود آماده می ساختند و مهارت های ضروری را خود به آنان می‌آموختند.</p><p>در سال ۱۹۰۶ میلادی تنظیم و تدوین خدمات راهنمایی شغلی توسط پارسونز كه به پدر راهنمایی حرفه‌ای معروف است، در بُستن (Boston)، واقع در آمریكا آغاز گردید.</p><p>اولین مركز راهنمایی كه در واقع مركز راهنمایی حرفه‌ای بود در سال ۱۹۰۸ میلادی در بوستون به وسیله وی تأسیس شد. در سال ۱۹۱۳ میلادی اوّلین خدمات راهنمایی شغلی به طور رسمی از طریق مؤسسه اطلاعات شغلی و حرفه ای بُستن ارائه گردید.</p><p>اصطلاح راهنمایی شغلی برای نخستین بار در جهان، در سال ۱۹۱۴ میلادی به طور رسمی، در كنگره ای كه در بروكسل تشكیل شده بود به كار رفت. ایالات متحده یكی از نخستین مکان هایی است كه در آن، مراكز ویژه راهنمایی و مشاوره شغلی تأسیس شده است.</p><p>پارسونز لازمه هدايت حرفه ای (مشاوره شغلی) را پیروی از سه اصل زير می دانست:<br />شناخت توانایی‌ها، علایق و مهارت های حرفه ای فرد<br />شناخت شغلی و موقعیت های شغلی<br />ایجاد ارتباط منطقی بین‌ دو اصل یاد شده<br />سال ۱۹۵۱، میلادی نقطه عطفی در تاریخچه راهنمایی شغلی در جهان محسوب می شود زیرا از این سال به بعد نظریه های انتخاب شغل مطرح گردید.</p><p>تالکوت پارسونز</p><p><strong>چرا انتخاب شغل مناسب و رضایت شغلی با اهمیت است؟</strong><br />فالمن و آرنولد رضایت شغلی را مجموعه گرایش های مثبت افراد نسبت به شغل دانسته و معتقدند وقتی گفته می‌شود یک فرد از شغل خود رضایت بالایی دارد، در حقیقت منظور این است كه وی بطور كلی به میزان زیاد شغل خود را دوست دارد و توانسته است از طریق شغلش نیازهای خویش را تأمین نماید و در نتیجه احساسات مثبتی نسبت به آن دارد.</p><p>رضایت شغلی از جمله عوامل مهمی است كه باید در توسعه اقتصادی مورد توجه دقیق قرار گیرد. هر فردی كوشش می‌كند شغلی را انتخاب نماید كه علاوه بر تأمین نیازهای مادی از نظر روانی نیز او را ارضاء نماید، به همین دلیل بررسی خصوصیات فردی افراد ضروری به نظر می‌رسد. در غیر اینصورت به كار گرفتن افراد در مشاغلی كه به آن علاقمند نیستند یا توانایی و استعداد انجام آن را ندارند، علاوه بر كاهش بهره‌ وری و كارایی موجب از دست رفتن نیروی انسانی می‌شود.</p><figure><img src=\"https://aghazgarclinic.ir/wp-content/uploads/2024/09/1c8b65341e984b0f8ba411c6c22d6b1a.jpg\" alt=\"\" /></figure><h2>رضایت شغلی و مدیر منابع انسانی</h2><p>اکثر سازمان ها برای رضایت کارکنان تلاش می‌کنند، اما همه به آن دست نیافتند. به همین دلیل برای متخصصان منابع انسانی مهم است که در مورد عواملی که می‌تواند رضایت کارکنان را افزایش دهد، و چگونگی حصول به موفقیت کلی در شرکت، بیشتر بدانند.</p><p>شکی نیست که کارکنان منبع شماره یک سازمان هستند. نگهداری شادی کارکنان کمک می‌کند که:</p><p>گ<strong>ردش مالی کمتر</strong></p><p>گردش مالی کارکنان یکی از بالاترین هزینه های مربوط به بخش منابع انسانی می باشد. رضایت کارکنان کمک می‌کند تا یک محیط بهتر ایجاد شود و با کارآمدی و ارتقا کیفیت کار به نحوی آسان تر در هزینه ها صرفه جویی شود. کارکنان راضی به احتمال کمتری کار خود را ترک می‌کنند.</p><p><strong>بهره وری بالاتر</strong></p><p>صرف نظر از عنوان شغلی و پرداخت حقوق، كاركنانی كه رضایت شغلی دارند، تمایل بیشتر و بهره وری بالاتری دارند.</p><p><strong>افزایش سود</strong></p><p>نگهداری کارکنان با ایمنی و رضایت می‌تواند منجر به فروش بیشتر، هزینه های پایین تر و خط مشی قوی تر شود.</p><p><strong>وفاداری</strong></p><p>هنگامی که کارکنان احساس می‌کنند که شرکت به بهترین وجه علاقه مند است از کارمندان خود حمایت کند. برای رسیدن به اهداف سخت تر کار می‌کنند. و ممکن است همکاران دیگر را نیز به این امر تشویق کنند.</p><p><strong>پیامد های ناشی از انتخاب نادرست شغل و نارضایتی شغلی</strong><br />کاهش بهره وری<br />خستگی مزمن<br />افسردگی<br />آسیب های جسمی ناشی از استرس شغلی<br />کاهش اعتماد و عزت نفس<br />سرخوردگی<br />فرسودگی شغلی<br />کاهش رضایت از زندگی و نهایتا فقر و بیکاری</p><h2>چه عواملی در رضایت شغلی تاثیرگذار هستند؟</h2><p>۱- عواملی که در مراحل قبل از انتخاب شغل می توانند در رسیدن به رضایت شغلی مؤثر باشند.<br />به احتمال زیاد فردی که در دوران تحصیل و قبل از انتخاب رشته از راهنمایی های مشاور شغلی تحصیلی، بهره مند شود در آینده رضایت شغلی بیشتری را احساس کرده و در زندگی موفق تر خواهد بود .</p><p>۲- عواملی که بعد از انتخاب شغل و در طی فرآیند انجام کار رضایت شغلی را ایجاد می‌نمایند. مشاوره شغلی در بحث سازمانی نیز معنا دارد.<br />در یک سازمان، مشاور شغلی به بررسی پست ها و سمت های سازمانی پرداخته و با انجام مصاحبه ها و گرفتن تست های روان شناسی و شخصیت شناسی مناسب از کارکنان، به شناخت کاملی می رسد و بهترین شغل را برای هر فرد در آن سازمان مشخص می کند.</p><p>این کار مشاوره شغلی علاوه بر افزایش کارآیی و بهره وری کارکنان سازمان، رضایت شغلی آنان را نیز فراهم می‌کند.</p>													<img width=\"822\" height=\"522\" src=\"https://aghazgarclinic.ir/wp-content/uploads/2025/01/academic-failure-5.webp\" alt=\"مشاوره تحصیلی\" srcset=\"https://aghazgarclinic.ir/wp-content/uploads/2025/01/academic-failure-5.webp 822w, https://aghazgarclinic.ir/wp-content/uploads/2025/01/academic-failure-5-300x191.webp 300w, https://aghazgarclinic.ir/wp-content/uploads/2025/01/academic-failure-5-768x488.webp 768w, https://aghazgarclinic.ir/wp-content/uploads/2025/01/academic-failure-5-600x381.webp 600w\" sizes=\"(max-width: 822px) 100vw, 822px\" />													<p><strong>چرا مراجعه به متخصص مشاور شغلی مهم است؟</strong><br />عواملی كه لزوم راهنمایی و مشاوره شغلی را در عصر حاضر اجتناب ناپذیر می‌كنند بروز دو پدیده توسعه شهر نشینی و پیشرفت تكنولوژی است.</p><p>شهرنشینی، تنوع و تقسیم مشاغل را باعث شده است و پیشرفت تكنولوژی نقش تخصص را در احراز شغل برجسته كرده است.</p><p>بوعلی سینا رعایت تفاوت های فردی و طبیعت و ذوق و سلیقه افراد را در برنامه ریزی آموزشی، اصل مهمی می‌داند كه نباید از آن غفلت كرد. وی پس از بیان واقعیت تفاوت های فردی در زمینه های گوناگون چنین می‌گوید:</p><p>شایسته است كه مربی کودک، هنگام گزینش حرفه یا دانش خاص، طبیعت کودک را آزموده، ذوق و سلیقه وی را سنجیده و میزان هوش وی را بیازماید. و بر این پایه حرفه یا دانش مناسب را برای کودک برگزینند (دفتر همکاری حوزه و دانشگاه، فلسفه تعلیم و تربیت).</p><p>چه بسا امروزه افراد با هوش و با استعدادی وجود دارند که فقط به دلیل این که در آن بازه زمانی حساس که باید برای شغل آینده و رشته تحصیلی خود چه در مقطع دانشگاهی و چه در مقاطع پایین تر، به مشاوران متخصص در زمینه شغلی تحصیلی، مراجعه می‌کردند تا آنها با توجه به تخصص خود در این زمینه و با در نظر گرفتن استعداد و خصوصیات شخصیتی و روانی آنها رشته و شغل متناسب به آنها را پیشنهاد دهند، مراجعه نکرده اند و متأسفانه با بسیاری از مشکلات روحی، روانی و اقتصادی دست و پنچه نرم می‌کنند.</p><p>با توجه به آنچه پیش تر مبنی بر اهمیت رضایت شغلی و همچنین پیامد های نامطلوب و زیان باری که نارضایتی شغلی، بر زندگی شخصی و اجتماعی فرد می‌گذارد، مشاوره شغلی تحصیلی برای داشتن آینده ای روشن و درخشان همچنین رضایت و امنیت در زندگی خود و فرزندانمان امری ضروری و اجتناب ناپذیر می‌باشد.</p><p><strong>ویژگی های مشاور شغلی و تحصیلی خوب چیست؟</strong><br />دارا بودن مهارت های ارتباطی<br />شناخت کامل ابزارهای سنجش شخصیت، رغبت شغلی، هوش و استعداد<br />توانایی برنامه ریزی و هدف گذاری برای مراجعان<br />شناخت کامل و به روز از مشاغل مختلف اعم از وضعیت در آمدی و شرایط بازار کار<br />فن بیان قوی</p><p>معرفی بهترین متخصصان مشاوره تحصیلی و شغلی کشور<br />در بسیاری از کشورهای پیشرفته در کنار موسساتی که دانش آموزان را برای اشتغال به کار تربیت می‌کنند، مراکز خاصی نیز برای راهنمایی و هدایت تحصیلی وجود دارد یکی از این مراکز که به ما در مشاوره تحصیلی و شغلی کمک می کنند <a href=\"https://aghazgarclinic.ir\" data-type=\"link\" data-id=\"https://aghazgarclinic.ir\">کلینیک روانشناسی آغازگر</a> است.</p><p>این مراکز که از راهنمایان با تجربه ای برخوردارهستند، با اتکا به روش ها و شیوه های علمی به مراجعان کمک می‌کنند تا ضمن انتخاب راه و روشی روشن، به خود و جامعه فایده رسانند.</p><p>همچنین پیشرفت علم و توسعه تکنولوژی و تنوع و تعدد بیش از حد مشاغل، انتخاب و تصمیم گیری شغلی را پیچیده و مشکل کرده است و با توجه به اینکه یکی از مهم ترین مراحل زندگی هر فرد ورود به عرصه کار و کسب درآمد است، بنابراین مراجعه به مشاوران و روانشناسان متخصص در زمینه شغلی تحصیلی برای داشتن زندگی بهتر، ضروری است.</p>','تخصص مشاوره تحصیلی و شغلی و معرفی بهترین مشاوران شغلی و تحصیلی','','publish','open','open','','hello-world','','','2026-04-03 19:34:06','2026-04-03 16:04:06','',0,'https://newsite.aghazgarclinic.ir/?p=1',0,'post','',0),
